/* R1327 — Franklin screenshot-driven UX refinement */
(()=>{'use strict';
const RELEASE='FR-NAV1.30.27-HF3.13.9';
const path=(location.pathname.replace(/\/+$/,'/')||'/');
const es=path==='/es/'||path.startsWith('/es/');
const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>[...r.querySelectorAll(s)];
const txt=(en,sp)=>es?sp:en;
const norm=s=>String(s||'').replace(/\s+/g,' ').trim();
const hasText=(el,re)=>el&&re.test(norm(el.textContent));
const addCss=()=>{if(q('link[data-r1327-refinement]'))return;const l=document.createElement('link');l.rel='stylesheet';l.href='/assets/r1327-refinement.css?v=frnav1327';l.dataset.r1327Refinement='1';document.head.append(l)};
const markRelease=()=>{const m=q('meta[name="franklin-release"]');if(m)m.content=RELEASE;document.documentElement.dataset.franklinRelease=RELEASE};
const emit=step=>{const detail={journey:'PROFILE_TO_MEMBERSHIP',step:String(step||'').slice(0,80)};window.dispatchEvent(new CustomEvent('franklin:business-journey',{detail}));try{window.dataLayer?.push?.({event:'franklin_business_journey',journey:detail.journey,step:detail.step})}catch{}};
const bindJourney=()=>{qa('a[href],button').forEach(el=>{if(el.dataset.r1327JourneyBound)return;const h=el.getAttribute('href')||'',t=norm(el.textContent).toLowerCase();let step='';if(/claim-profile/.test(h)||t.includes('find or manage')||t.includes('find my profile'))step='FIND_PROFILE';else if(/member-profile-preview/.test(h)||t.includes('preview')&&t.includes('profile'))step='PREVIEW_MEMBER_PROFILE';else if(/membership-start/.test(h)||t.includes('see membership')||t.includes('review community membership'))step='MEMBERSHIP_DETAILS';else if(/membership-enroll/.test(h)||t.includes('start membership')||t.includes('continue — $35'))step='MEMBERSHIP_SETUP';if(step){el.dataset.r1327JourneyBound='1';el.addEventListener('click',()=>emit(step))}})};
function assistantStartState(){if(path!=='/'&&path!=='/es/')return;const root=q('[data-navigator-bot]')||q('#ask-navigator')||document;const clear=qa('a,button',root).find(el=>/clear\s*\/\s*new question|borrar\s*\/\s*nueva pregunta/i.test(norm(el.textContent)));if(!clear)return;const form=q('form',root);const set=start=>{clear.hidden=Boolean(start);clear.setAttribute('aria-hidden',start?'true':'false')};set(true);form?.addEventListener('submit',()=>set(false));clear.addEventListener('click',()=>setTimeout(()=>set(true),0));}
function homepage(){if(path!=='/'&&path!=='/es/')return;
  assistantStartState();
  const network=q('.r1311-community-actions');if(network)network.classList.add('r1327-network');
  const details=qa('details').find(d=>/explore activities, sports, learning and clubs|explorar actividades, deportes, aprendizaje y clubes/i.test(norm(q('summary',d)?.textContent)));
  if(details){details.classList.add('r1327-activities-disclosure');details.closest('section')?.classList.add('r1327-activities-section')}
  const business=q('.r24-business-section');if(business){const notes=qa('p',business).filter(p=>/payment is not required|basic public profiles, factual corrections|membership is optional|no se requiere pago|los perfiles públicos básicos/i.test(norm(p.textContent)));let keeper=q('.r1326-business-trust',business)||notes.at(-1);if(keeper){keeper.hidden=false;keeper.textContent=txt('Basic public profiles, factual corrections and removal requests stay free. Community Membership is optional and does not buy ranking, endorsement or guaranteed leads.','Los perfiles públicos básicos, las correcciones factuales y las solicitudes de eliminación siguen siendo gratis. La Membresía Comunitaria es opcional y no compra clasificación, respaldo ni clientes potenciales garantizados.');notes.forEach(n=>{if(n!==keeper)n.hidden=true})}}
}
function business(){if(path!=='/business-dashboard/'&&path!=='/es/negocios/')return;
  const flow=q('.hf310-path.r1326-flow')||q('.hf310-path');if(flow){flow.classList.add('r1327-path');qa(':scope > span',flow).forEach((card,i)=>{card.classList.add('r1327-path-card');card.dataset.step=String(i+1)})}
  const duplicate=q('.hf310-dashboard-membership');if(duplicate){const card=q('.hf310-dashboard-card',duplicate)||q('article',duplicate)||duplicate;card.classList.add('r1327-membership-continuation');const title=q('h2',card),list=q('ul',card),cta=q('a.button',card);if(title)title.textContent=txt('Want to look closer at Community Membership?','¿Quiere ver más de cerca la Membresía Comunitaria?');if(list)list.remove();const p=qa('p',card).find(x=>!x.classList.contains('fine-print'));if(p)p.textContent=txt('See the full $35/year membership details and preview before deciding. Your public profile and factual corrections stay free.','Vea los detalles completos de la membresía de $35/año y la vista previa antes de decidir. Su perfil público y las correcciones factuales siguen siendo gratis.');if(cta){cta.href=es?'/es/iniciar-membresia/':'/membership-start/';cta.textContent=txt('Review Community Membership — $35/year','Revisar Membresía Comunitaria — $35/año')}}
  const trust=qa('p,.hf37-trust-note,.r1326-no-pay').filter(el=>/no paid ranking|corrections and removal are always free|membership does not affect ordinary directory|sin clasificación pagada|correcciones y eliminación/i.test(norm(el.textContent)));if(trust.length>1)trust.slice(1).forEach(el=>el.hidden=true);
  const free=qa('details').find(d=>/^free business tools|^herramientas gratuitas/i.test(norm(q('summary',d)?.textContent)));if(free){const s=q('summary',free);s.textContent=txt('Free business tools — Growth Planner, Growth Guides & Franklin Assistant','Herramientas gratuitas — Planificador de crecimiento, guías y Franklin Assistant')}
}
function membershipStart(){if(path!=='/membership-start/'&&path!=='/business-membership/'&&path!=='/es/iniciar-membresia/')return;
  const hero=q('main section:first-child');const actions=q('.actions',hero||document);if(actions){actions.innerHTML=es?'<a class="button primary" href="/claim-profile/">Buscar o administrar mi perfil primero</a><a class="button" href="/member-profile-preview/">Vista previa del perfil de miembro</a>':'<a class="button primary" href="/claim-profile/">Find or manage my profile first</a><a class="button" href="/member-profile-preview/">Preview the member profile</a>'}
  const example=q('.hf310-member-example');if(example&&!q('.r1327-example-label',example)){example.classList.add('r1327-example');const label=document.createElement('div');label.className='eyebrow r1327-example-label';label.textContent=txt('Example member profile','Ejemplo de perfil de miembro');example.prepend(label);const strong=q('strong',example);if(strong)strong.textContent=txt('Example business','Negocio de ejemplo');const span=q('span',strong?.parentElement||example);if(span)span.textContent=txt('Category · location · reviewed About · services · hours · photos · eligible official actions','Categoría · ubicación · información revisada · servicios · horarios · fotos · acciones oficiales elegibles')}
  const decision=q('.hf310-decision-card');if(decision){const list=q('ul',decision);if(list)list.innerHTML=es?'<li>Perfil revisado más completo con información, servicios y horarios</li><li>Enlaces oficiales y de acción para clientes verificados cuando correspondan</li><li>Fotos y participación local cuando estén respaldadas</li><li>Sin Perfiles locales similares en el perfil de miembro activo</li><li>Herramientas y apoyo para miembros cuando correspondan</li>':'<li>Richer reviewed profile with About, services and hours</li><li>Verified official and customer-action links where applicable</li><li>Photos and local participation where supported</li><li>No Similar local profiles on the active member profile</li><li>Applicable member tools and support</li>';const cta=q('a.button.primary',decision);if(cta){cta.href='/membership-enroll/';cta.textContent=txt('Start membership setup — $35/year','Iniciar membresía — $35/año')}}
  const first=q('.r1326-membership-start-first .r1326-no-pay');if(first)first.textContent=txt('Membership does not buy accuracy, ranking or endorsement, and it does not guarantee leads or customers.','La membresía no compra precisión, clasificación ni respaldo, y no garantiza clientes potenciales ni clientes.');
  const free=q('.hf310-always-free');if(free)free.innerHTML=txt('<strong>Always free:</strong> factual corrections and public-profile removal.','<strong>Siempre gratis:</strong> correcciones factuales y eliminación del perfil público.');
  const policy=qa('details').find(d=>/membership details.*profile review|detalles de membresía/i.test(norm(q('summary',d)?.textContent)));if(policy){q('summary',policy).textContent=txt('Membership details, billing & profile review','Detalles de membresía, facturación y revisión del perfil');const div=q('div',policy);if(div)div.innerHTML=txt('<p><strong>$35/year, billed annually until canceled.</strong> Secure checkout and billing are handled through Stripe after profile representation is confirmed.</p><p>Your basic public profile, factual corrections and removal requests remain free. Public-source facts and member-provided information stay separate; new or changed member content is reviewed before publication.</p><p>Membership does not buy ranking, endorsement, credentials, leads or guaranteed results.</p>','<p><strong>$35/año, facturado anualmente hasta cancelar.</strong> El pago seguro y la facturación se gestionan mediante Stripe después de confirmar la representación del perfil.</p><p>Su perfil público básico, las correcciones factuales y las solicitudes de eliminación siguen siendo gratis. Los datos de fuentes públicas y la información proporcionada por miembros permanecen separados; el contenido nuevo o modificado se revisa antes de publicarse.</p><p>La membresía no compra clasificación, respaldo, credenciales, clientes potenciales ni resultados garantizados.</p>')}
}
function claim(){if(path!=='/claim-profile/')return;const hero=q('.hf37-claim-hero');const form=q('[data-hf310-claim-search-form]');const results=q('[data-hf310-claim-results]');if(hero&&!q('.r1327-claim-next',hero)){const n=document.createElement('div');n.className='r1327-claim-next';n.innerHTML='<strong>What happens next</strong><span>Choose the matching public profile → review its facts or request free corrections/removal → preview Community Membership only if it is useful to you.</span>';q('.hf37-missing-profile',hero)?.insertAdjacentElement('afterend',n)}if(results){results.setAttribute('role','status');results.setAttribute('aria-atomic','true')}let explicit=false;form?.addEventListener('submit',()=>{explicit=true;results?.setAttribute('aria-busy','true')});if(results){new MutationObserver(()=>{results.removeAttribute('aria-busy');if(explicit){const b=q('button',results);if(b)b.focus();explicit=false}}).observe(results,{childList:true,subtree:true,characterData:true})}}
function preview(){if(path!=='/member-profile-preview/')return;const hero=q('main section:first-child');const fallback=qa('a.button',hero||document).find(a=>/business not listed/i.test(norm(a.textContent)));if(fallback)fallback.textContent="Can't find your profile?";const ctx=q('[data-hf310-profile-context]');const form=q('[data-r28-preview-form]');const preview=q('[data-r28-preview]');if(ctx&&!q('.r1327-preview-safety',ctx.parentElement)){const n=document.createElement('div');n.className='r1327-preview-safety';n.innerHTML='<strong>Preview only.</strong> Nothing you type here is published and no membership or payment is created. Proposed changes are reviewed separately before publication. Do not enter confidential customer, patient, client, account, payment, medical or legal-case information.';ctx.insertAdjacentElement('afterend',n)}if(preview)preview.classList.add('r1327-sticky-preview');
  if(form){const sections=qa('details.hf310-editor-section',form);const defs=[['about','services','hours','languages'],['booking','quote','order','directions','linkedin','facebook','instagram','youtube','x','tiktok','threads','online'],['photos']];const base=[txt('About & services','Información y servicios'),txt('Action links & online presence','Enlaces de acción y presencia en línea'),txt('Photos / gallery','Fotos / galería')];sections.slice(1).forEach((d,i)=>{const summary=q('summary',d);if(summary)summary.dataset.r1327Base=base[i]||norm(summary.textContent)});
    const actionDetails=sections.find(d=>/action links/i.test(norm(q('summary',d)?.textContent)));const body=q('.hf310-editor-body',actionDetails||document);if(body&&!q('[name="youtube"]',body)){const row1=document.createElement('div');row1.className='hf37-form-two r1327-extra-socials';row1.innerHTML='<label>YouTube<input name="youtube" placeholder="https://youtube.com/…"></label><label>X<input name="x" placeholder="https://x.com/…"></label>';const row2=document.createElement('div');row2.className='hf37-form-two r1327-extra-socials';row2.innerHTML='<label>TikTok<input name="tiktok" placeholder="https://tiktok.com/…"></label><label>Threads<input name="threads" placeholder="https://threads.net/…"></label>';const note=qa('p.fine-print',body).at(-1);note?.before(row1,row2)}
    const initial=new Map();let sourceMarked=false;const markSources=()=>{if(sourceMarked)return;const context=norm(ctx?.textContent);if(!/existing public facts are prefilled|selected profile/i.test(context.toLowerCase()))return;qa('input,textarea',form).forEach(f=>{if(f.value){initial.set(f.name,f.value);f.closest('label')?.classList.add('r1327-source-backed')}});sourceMarked=true;updateFieldState()};
    const updateFieldState=()=>{qa('input,textarea',form).forEach(f=>{const label=f.closest('label');if(!label)return;label.classList.remove('r1327-proposed');if(initial.has(f.name)&&f.value===initial.get(f.name)){label.classList.add('r1327-source-backed')}else{label.classList.remove('r1327-source-backed');if(String(f.value||'').trim())label.classList.add('r1327-proposed')}});sections.slice(1).forEach((d,i)=>{const summary=q('summary',d);if(!summary)return;const names=defs[i]||[];const count=names.filter(n=>{const f=form.elements[n];return f&&(f.type==='checkbox'?f.checked:String(f.value||'').trim())}).length;summary.textContent=`${summary.dataset.r1327Base||base[i]} — ${count?`${count} added`:'optional'}`})};
    const patchPreview=()=>queueMicrotask(()=>{if(!preview)return;const actions=q('.hf310-preview-actions',preview);if(actions){const entered=['website','phone','email','booking','quote','order','directions'].some(n=>String(form.elements[n]?.value||'').trim());if(!entered)actions.innerHTML='<span>Eligible customer actions appear here after qualified links are supplied and reviewed.</span>';else if(!q('.r1327-pending-note',actions)){const n=document.createElement('small');n.className='r1327-pending-note';n.textContent='Preview actions — verification is required before publication.';actions.append(n)}}const online=q('.hf310-online-list',preview);const extras=[['YouTube','youtube'],['X','x'],['TikTok','tiktok'],['Threads','threads']].filter(([,n])=>String(form.elements[n]?.value||'').trim());if(online){if(!qa('span',online).some(s=>/pending verification/i.test(s.textContent))&&([...qa('span',online)].length||extras.length)){extras.forEach(([label])=>{if(!qa('span',online).some(s=>norm(s.textContent)===label)){const s=document.createElement('span');s.textContent=label;online.append(s)}});const n=document.createElement('span');n.className='r1327-pending-online';n.textContent='Pending verification before publication';online.append(n)}}});
    form.addEventListener('input',()=>{updateFieldState();patchPreview()});form.addEventListener('change',()=>{updateFieldState();patchPreview()});new MutationObserver(()=>{markSources();patchPreview()}).observe(ctx||form,{childList:true,subtree:true,characterData:true});setTimeout(()=>{markSources();updateFieldState();patchPreview()},350)}
  const cta=qa('a.button.primary').find(a=>/review community membership/i.test(norm(a.textContent)));if(cta)cta.textContent=txt('Review Community Membership — $35/year','Revisar Membresía Comunitaria — $35/año');
}
function enrollment(){if(path!=='/membership-enroll/')return;const hero=q('main section:first-child');if(hero){const h=q('h1',hero),p=q('.r29-lead',hero);if(h)h.textContent='Set up Community Membership';if(p)p.innerHTML='Start with your existing Franklin profile. Account creation and representation verification come before checkout. <strong>$35/year</strong> is charged only after verification and your explicit checkout choice.';if(!q('.r1327-enroll-trust',hero)){const n=document.createElement('p');n.className='fine-print r1327-enroll-trust';n.textContent='Basic public profiles, factual corrections and removal requests remain free. No payment is required to correct profile facts.';q('.wrap',hero)?.append(n)}}const progress=q('.r37-member-progress');if(progress)progress.classList.add('r1327-enroll-progress');const root=q('[data-membership-live-root]');if(root){root.setAttribute('aria-live','polite');root.setAttribute('aria-busy','true');new MutationObserver(()=>{root.removeAttribute('aria-busy');qa('.r37-search-result',root).forEach(b=>{const last=qa('span',b).at(-1);if(last&&/this is my profile/i.test(norm(last.textContent)))last.textContent='Choose profile'})}).observe(root,{childList:true,subtree:true,characterData:true})}}
function run(){addCss();markRelease();homepage();business();membershipStart();claim();preview();enrollment();bindJourney();setTimeout(bindJourney,500)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run,{once:true});else run();
})();
